def parabola_vertex(a, b, c):
    """Return the vertex ``(x, y)`` of ``y = a*x**2 + b*x + c``.

    Raises:
        ValueError: If ``a`` is zero, since that is not a parabola.
    """
    if a == 0:
        raise ValueError("'a' must be non-zero for a parabola")
    x_vertex = -b / (2 * a)
    y_vertex = a * x_vertex**2 + b * x_vertex + c
    return (x_vertex, y_vertex)
